module network_optimizer (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] diam1,\n    input [7:0] diam2,\n    input [7:0] diam3,\n    input [7:0] diam4,\n    input [2:0] num_trees,\n    output reg [7:0] result,\n    output reg done\n);\n\n    reg [7:0] radii [0:3];\n    reg [7:0] max_diam;\n    reg [7:0] temp_result;\n    reg [2:0] state;\n    reg [2:0] i;\n    \n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COMPUTE_RADII = 3'd1;\n    localparam [2:0] FIND_MAX = 3'd2;\n    localparam [2:0] CALCULATE = 3'd3;\n    localparam [2:0] DONE_STATE = 3'd4;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            result <= 8'd0;\n            done <= 1'b0;\n            state <= IDLE;\n            max_diam <= 8'd0;\n            temp_result <= 8'd0;\n            i <= 3'd0;\n            radii[0] <= 8'd0;\n            radii[1] <= 8'd0;\n            radii[2] <= 8'd0;\n            radii[3] <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    max_diam <= 8'd0;\n                    temp_result <= 8'd0;\n                    if (start && (num_trees >= 3'd1) && (num_trees <= 3'd4)) begin\n                        state <= COMPUTE_RADII;\n                        i <= 3'd0;\n                    end\n                end\n                \n                COMPUTE_RADII: begin\n                    case (i)\n                        3'd0: radii[0] <= (diam1 + 8'd1) >> 1;\n                        3'd1: radii[1] <= (diam2 + 8'd1) >> 1;\n                        3'd2: radii[2] <= (diam3 + 8'd1) >> 1;\n                        3'd3: radii[3] <= (diam4 + 8'd1) >> 1;\n                    endcase\n                    if (i < (num_trees - 3'd1)) begin\n                        i <= i + 3'd1;\n                    end else begin\n                        state <= FIND_MAX;\n                        i <= 3'd0;\n                    end\n                end\n                \n                FIND_MAX: begin\n                    case (i)\n                        3'd0: if (diam1 > max_diam) max_diam <= diam1;\n                        3'd1: if (diam2 > max_diam) max_diam <= diam2;\n                        3'd2: if (diam3 > max_diam) max_diam <= diam3;\n                        3'd3: if (diam4 > max_diam) max_diam <= diam4;\n                    endcase\n                    if (i < (num_trees - 3'd1)) begin\n                        i <= i + 3'd1;\n                    end else begin\n                        temp_result <= max_diam;\n                        state <= CALCULATE;\n                    end\n                end\n                \n                CALCULATE: begin\n                    if (num_trees >= 3'd2) begin\n                        if ((radii[0] + radii[1] + 8'd1) > temp_result)\n                            temp_result <= radii[0] + radii[1] + 8'd1;\n                    end\n                    if (num_trees >= 3'd3) begin\n                        if ((radii[0] + radii[1] + radii[2] + 8'd2) > temp_result)\n                            temp_result <= radii[0] + radii[1] + radii[2] + 8'd2;\n                    end\n                    if (num_trees >= 3'd4) begin\n                        if ((radii[0] + radii[1] + radii[2] + radii[3] + 8'd2) > temp_result)\n                            temp_result <= radii[0] + radii[1] + radii[2] + radii[3] + 8'd2;\n                    end\n                    state <= DONE_STATE;\n                end\n                \n                DONE_STATE: begin\n                    result <= temp_result;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule